/* Original procedural miniature landscape. No reference-image assets. */
function buildTinyWorld(root){
 const T=AFRAME.THREE;
 const add=(tag,a,p=root)=>{const e=document.createElement(tag);for(const[k,v]of Object.entries(a))e.setAttribute(k,v);p.append(e);return e};
 const group=(x,y,z,s=1,p=root)=>add('a-entity',{position:`${x} ${y} ${z}`,scale:`${s} ${s} ${s}`},p);
 function terrain(p,radius=3,depth=1.6){const count=48,vertices=[],colors=[],indices=[],top=new T.Color('#a9c7a6'),edge=new T.Color('#729e91'),rock=new T.Color('#a4a7b4');
  for(let ring=0;ring<4;ring++){for(let i=0;i<count;i++){const a=i/count*Math.PI*2,irregular=1+.045*Math.sin(a*5)+.035*Math.cos(a*7);const r=[0,.55,1, .42][ring]*radius*irregular;const y=[.19,.12,-.04,-depth][ring]+(ring>0?Math.sin(a*3)*.06:0);vertices.push(Math.cos(a)*r,y,Math.sin(a)*r*.76);const c=(ring<2?top:ring===2?edge:rock).clone().multiplyScalar(.91+.09*Math.sin(i*3+ring));colors.push(c.r,c.g,c.b)}}
  for(let ring=0;ring<3;ring++)for(let i=0;i<count;i++){const j=(i+1)%count,a=ring*count+i,b=ring*count+j,c=(ring+1)*count+i,d=(ring+1)*count+j;indices.push(a,c,b,b,c,d)}
  const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(vertices,3));geometry.setAttribute('color',new T.Float32BufferAttribute(colors,3));geometry.setIndex(indices);geometry.computeVertexNormals();const land=new T.Mesh(geometry,new T.MeshStandardMaterial({vertexColors:true,roughness:1,flatShading:true,side:T.DoubleSide}));const host=add('a-entity',{},p);host.object3D.add(land);
 }
 function tree(x,y,z,s=1,p=root){const t=group(x,y,z,s,p);t.object3D.userData.lensSubject='trees';add('a-cylinder',{position:'0 .32 0',radius:'.043',height:'.64',color:'#8e7c67','segments-radial':10,material:'roughness:1'},t);for(const [bx,by,bz,angle] of [[-.12,.48,0,32],[.12,.52,.03,-30],[.02,.57,-.1,-18]])add('a-cylinder',{position:`${bx} ${by} ${bz}`,rotation:`0 ${bz?-45:0} ${angle}`,radius:'.021',height:'.36',color:'#94816c','segments-radial':8},t);const crowns=[[0,.88,0,.3],[-.23,.72,.03,.25],[.24,.77,-.02,.25],[.02,1.08,.01,.23],[-.15,.99,-.15,.23],[.18,.98,.14,.23],[.02,.72,.23,.23],[-.05,.84,-.25,.24],[-.29,.85,-.1,.19],[.3,.9,.04,.18],[-.16,.91,.25,.18],[.12,1.15,-.08,.17],[.17,.68,.16,.18]];const leaves=new T.InstancedMesh(new T.SphereGeometry(1,12,8),new T.MeshStandardMaterial({roughness:.95}),crowns.length+12),matrix=new T.Matrix4(),q=new T.Quaternion(),leafColor=new T.Color();crowns.forEach(([a,b,c,r],i)=>{matrix.compose(new T.Vector3(a,b,c),q,new T.Vector3(r*(1+(i%3)*.08),r*(.84+(i%2)*.1),r));leaves.setMatrixAt(i,matrix);leaves.setColorAt(i,leafColor.set(['#4f8058','#69965f','#82a96b','#5c8b58','#93b779'][i%5]))});for(let i=0;i<12;i++){const angle=i*2.399,r=.22+(i%3)*.045,size=.075+(i%2)*.025;matrix.compose(new T.Vector3(Math.cos(angle)*r,.79+(i%4)*.09,Math.sin(angle)*r),q,new T.Vector3(size,size*.65,size*.9));leaves.setMatrixAt(crowns.length+i,matrix);leaves.setColorAt(crowns.length+i,leafColor.set(i%2?'#8bb574':'#719f63'))}leaves.instanceMatrix.needsUpdate=true;leaves.instanceColor.needsUpdate=true;leaves.computeBoundingSphere();const foliage=add('a-entity',{},t);foliage.object3D.add(leaves);return t}
 function pavilion(x,y,z,s=1,p=root,roof='#7f9bb9'){const g=group(x,y,z,s,p);add('a-cylinder',{position:'0 .045 0',radius:'.39',height:'.09',color:'#f4eadb','segments-radial':24},g);for(let i=0;i<6;i++){const a=i/6*Math.PI*2;add('a-cylinder',{position:`${Math.cos(a)*.28} .36 ${Math.sin(a)*.28}`,radius:'.025',height:'.6',color:'#f7f4ee','segments-radial':8},g)}add('a-cone',{position:'0 .73 0','radius-bottom':'.48','radius-top':'.06',height:'.26',color:roof,'segments-radial':12},g);add('a-sphere',{position:'0 .9 0',radius:'.035',color:'#e3c79c'},g);return g}
 function path(points,width,color,p){const vertices=[],indices=[];for(let i=0;i<points.length;i++){const prev=points[Math.max(0,i-1)],next=points[Math.min(points.length-1,i+1)],dx=next[0]-prev[0],dz=next[2]-prev[2],length=Math.hypot(dx,dz)||1;const nx=-dz/length*width/2,nz=dx/length*width/2;vertices.push(points[i][0]+nx,points[i][1],points[i][2]+nz,points[i][0]-nx,points[i][1],points[i][2]-nz);if(i<points.length-1){const j=i*2;indices.push(j,j+2,j+1,j+1,j+2,j+3)}}const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(vertices,3));geometry.setIndex(indices);geometry.computeVertexNormals();const host=add('a-entity',{},p);host.object3D.add(new T.Mesh(geometry,new T.MeshStandardMaterial({color,roughness:.68,side:T.DoubleSide})));}
 const main=group(0,-.12,-1.8);terrain(main,3.2,1.7);
 // A shallow lake and a river that spills over the front of the island.
 main.setAttribute('living-water','');
 path([[-2.65,.04,.2],[-2,.14,.6],[-1.35,.2,.9],[-.6,.24,1.1],[.2,.21,1.1],[1,.2,.95],[1.8,.13,.5],[2.65,.04,0]],.18,'#f1e7d5',main);
 path([[-1.4,.2,.9],[-1.1,.2,.1],[-1.3,.15,-.6],[-1.8,.07,-1.1]],.13,'#f1e7d5',main);
 // Original arched footbridge over the miniature river.
 for(let i=0;i<11;i++){const t=i/10;add('a-box',{position:`${-.2+t*.7} ${.31+Math.sin(t*Math.PI)*.1} 1.19`,width:'.065',height:'.04',depth:'.4',color:'#ddcbb5'},main)}
 for(const z of [.98,1.4]){path([[-.24,.39,z],[-.05,.46,z],[.15,.48,z],[.35,.44,z],[.55,.37,z]],.022,'#fff5e7',main)}
 // Globe garden, with a sculpted white observatory ring.
 add('a-cylinder',{position:'0 .34 -.65',radius:'.56',height:'.28',color:'#f6f1e8','segments-radial':32},main);add('a-torus',{position:'0 .5 -.65',rotation:'90 0 0',radius:'.56','radius-tubular':'.025',color:'#b5cced'},main);
 pavilion(-1.65,.12,-.65,.9,main);pavilion(1.75,.1,-.7,.65,main,'#b4a4c0');
 const forest=[[-2.5,.03,-.3,.95],[-2.15,.08,-1,.8],[-1.45,.13,-1.5,.7],[1.1,.15,-1.6,.85],[2.4,.03,-.35,.95],[2.05,.1,.65,.7],[-1.75,.12,1.15,.65],[-.85,.16,-1.8,.5],[.9,.2,1.55,.55]];forest.forEach(v=>tree(...v,main));
 for(let i=0;i<24;i++){const a=i*2.399,r=1.15+(i%5)*.3;add('a-dodecahedron',{position:`${Math.cos(a)*r} .13 ${Math.sin(a)*r*.7}`,radius:.04+(i%3)*.018,scale:'1 .65 1',color:i%3===0?'#d7b7ce':i%3===1?'#f1d2a4':'#becda3'},main)}
 // Six distinctive regional satellites around the tiny world.
 const satellitePositions=[[-4.6,.15,-3.4],[-3.7,.5,-6.7],[0,.8,-7.8],[3.7,.5,-6.7],[4.6,.15,-3.4],[0,-.5,3.1]];
 satellitePositions.forEach(([x,y,z],i)=>{const island=group(x,y,z,.78);island.setAttribute('visible',false);terrain(island,1.2,.8);pavilion(-.3,.1,-.15,.7,island,['#8b9fbe','#c3a8bd','#ccaa82','#9aac9e','#8ab0bd','#b6a7c6'][i]);tree(.55,.05,-.2,.65,island);tree(-.55,.07,.5,.45,island);add('a-torus',{position:'0 .18 0',rotation:'90 0 0',radius:'1.24','radius-tubular':'.012',color:'#d6e4f6'},island);const marker=add('a-sphere',{position:'.1 1.2 .2',radius:'.085',color:'#6caeff',material:'shader:flat'},island);marker.id='regionBeacon'+i;marker.addEventListener('click',()=>window.globiquest?.chooseRegion(i));const label=group(x,y+1.55,z);label.id='regionLabel'+i;label.setAttribute('visible',false);});
 // No decorative cloud meshes: keep the tiny-world view clear.


}
